// The second set of free tools (getgradify.com/tools/…): planners, timers, calculators and writing helpers. Each page
// answers first (what it does, three steps, who it's for), then the tool, a worked example you can load into it, a
// short FAQ and the tools that usually come next. The tool's code: assets/tools-plan.js or assets/tools-write.js
// (data-mod), run by assets/seo.js, which adds Try an example, Reset, Copy summary, Share link, Print and Embed.
import { faq, related, esc } from "./shell.mjs";

const U = "2026-11-23";
export const CATS = { grades: "Grades and marks", plan: "Plan your revision", focus: "Focus and wellbeing", write: "Coursework and writing", exam: "Exam technique" };
const APP = (name, slug) => ({ "@type": "WebApplication", name, url: `https://getgradify.com/tools/${slug}/`, applicationCategory: "EducationalApplication", operatingSystem: "Web", browserRequirements: "Requires JavaScript", isAccessibleForFree: true, offers: { "@type": "Offer", price: "0", priceCurrency: "GBP" }, publisher: { "@id": "https://getgradify.com/#org" } });
const i = (name, label, attrs = "") => `<div><label for="${name}">${label}</label><input id="${name}" name="${name}" ${attrs}></div>`;
const n = (name, label, value, attrs = "") => i(name, label, `type="number" value="${value}" inputmode="decimal" ${attrs}`);
const ta = (name, label, rows = 5, ph = "") => `<div class="full"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" rows="${rows}" placeholder="${esc(ph)}"></textarea></div>`;
const sel = (name, label, opts) => `<div><label for="${name}">${label}</label><select id="${name}" name="${name}">${opts.map(([v, l, on]) => `<option value="${v}"${on ? " selected" : ""}>${l}</option>`).join("")}</select></div>`;
const RES = '<div class="result" role="status" aria-live="polite"></div>';
const rows = (add) => `<div class="rows"></div><div class="actions"><button type="button" class="ghost" data-add>${add}</button></div>`;
const conf = [["1", "1: lost"], ["2", "2: shaky"], ["3", "3: OK", 1], ["4", "4: good"], ["5", "5: confident"]];

