// countdown pages for each exam season (assets/study-tools.js countdown, kept apart with data-key)
const SEASONS = [
  ["gcse-exam-countdown", "GCSE exam countdown 2027", "gcse", "2027-05-10", "GCSE exams in England, Wales and Northern Ireland usually start in the second week of May and run to late June."],
  ["a-level-exam-countdown", "A level exam countdown 2027", "alevel", "2027-05-11", "A level exams usually start in mid-May and finish in late June."],
  ["uni-finals-countdown", "University finals countdown", "finals", "2027-05-17", "Most UK universities hold summer exams from mid-May to early June; January exams run in the first three weeks of January."],
];
for (const [slug, name, key, date, when] of SEASONS) TOOLS2.push({
  slug, cat: "plan", mod: "study-tools", tool: "countdown", key, name, line: "Days to go and real revision hours left.", best: "Best for keeping the whole season in view",
  title: `${name.replace(/ 2027$/, "")}: Days Left and Revision Hours (2027) · Gradify`, description: `How many days until ${name.replace(/ countdown.*$/, "")}s? A free countdown with revision hours left, an embeddable widget and a story card to share.`,
  answer: `${when} The date below is an <b>estimate</b>: change it to your first paper from your exam board's or university's published timetable. You'll see the days left, study days after rest days and your real revision hours.`,
  ui: `<div class="grid"><div><label for="label">Exam</label><input id="label" name="label" type="text" maxlength="40" value="${esc(name.replace(/ countdown.*$/, ""))}"></div><div><label for="exam">First exam</label><input id="exam" name="exam" type="date" value="${date}"></div><div><label for="hours">Hours a day</label><input id="hours" name="hours" type="number" min="0.5" max="14" step="0.5" value="3"></div><div><label for="rest">Rest days a week</label><select id="rest" name="rest"><option>0</option><option selected>1</option><option>2</option></select></div></div>${RES}<div class="actions"><button type="button" class="ghost" data-card>Download a story card</button></div><h2 class="h3">Put this countdown on your site or Notion</h2><label for="embed">Embed code</label><textarea id="embed" rows="4" readonly data-embed></textarea><div class="actions"><button type="button" class="ghost" data-copy-embed>Copy embed code</button></div>`,
  worked: "With 24 weeks to go and 3 hours a day with one rest day a week, you have about 144 study days and 430 revision hours. Split by subject and topic, then keep the last two weeks for past papers.",
  faq: [["When do the 2027 exams start?", "Exam boards publish final timetables months ahead. Typical patterns: GCSEs and A levels from mid-May to late June, university summer exams mid-May to early June. Always check your own timetable."]],
  next: [["tools/exam-timetable-planner/", "Exam timetable planner"], ["study-plan/", "Study plans"]],
});

/** the page for one tool */
export function toolPage(t, all) {
  const f = faq(t.faq), ex = t.example ? ` data-example='${JSON.stringify(t.example).replace(/'/g, "&#39;")}'` : "";
  const nextLinks = (t.next || []).map(([h, l]) => (h.includes("/") ? [h, l] : [`tools/${h}/`, l]));
  const sameCat = all.filter((x) => x.cat === t.cat && x.slug !== t.slug).slice(0, 4).map((x) => [`tools/${x.slug}/`, x.name, x.line]);
  return {
    path: `tools/${t.slug}/index.html`, title: t.title, description: t.description, updated: U, crumbs: [["Free study tools", "tools/"], [t.name, `tools/${t.slug}/`]],
    schema: [APP(t.name, t.slug), f.schema],
    body: `<h1>${esc(t.name)}</h1><p class="answer">${t.answer}</p>
    <p class="tool-tools no-print"><button type="button" class="mini" data-pin>☆ Pin this tool</button> <button type="button" class="mini" data-focus>Focus mode</button> <span class="best">${esc(t.best)}</span></p>
    <div class="tool" data-tool="${t.tool}" data-mod="${t.mod}"${t.key ? ` data-key="${t.key}"` : ""}${t.bar === false ? ' data-bar="off"' : ""}${ex}>
      ${t.ui}
      <noscript><p>This tool runs in your browser and needs JavaScript. The worked example below shows the method.</p></noscript>
    </div>
    <h2>Worked example</h2><p>${t.worked}</p>${t.example ? '<p class="no-print"><button type="button" class="mini" data-load-example>Load this example into the tool</button></p>' : ""}
    <h2>Who it's for</h2><p>${esc(t.best)}. Free, no account, and nothing you type leaves your browser: it's saved on this device so it's here next time.</p>
    ${f.html}${related("What to use next", [...nextLinks.map(([h, l]) => [h, l, ""]), ...sameCat].slice(0, 6))}
    <p class="hub-back"><a href="/tools/">← All free study tools</a></p>`,
  };
}
export const tools2Pages = () => TOOLS2.map((t) => toolPage(t, TOOLS2));
